INSERT INTO `questions` (`category_id`, `type`, `title`, `options`, `answer`, `explanation`) VALUES 
(3, 'single', '(变种 1) Vue 3 中的响应式数据核心实现是基于以下哪种技术？', '["A. Object.defineProperty","B. ES6 Proxy","C. MutationObserver","D. Getter/Setter 劫持"]', 'B', 'Vue3 全面拥抱了 ES6 的 Proxy，解决了 Vue2 中对象属性增删无法被追踪的问题。'),
(3, 'single', '(变种 2) 在 setup 语法糖中，以下哪种修改响应式数据的方式是正确的？', '["A. count = 1","B. count.value = 1","C. this.count = 1","D. set(count, 1)"]', 'B', '被 ref 包装的数据，在 JS 逻辑中必须通过 .value 进行读取和修改。在模板中则会自动解包。'),
